# Pseudocode for intercept_external_help_seeking
# Input:
#   - user_id: str
#   - activity_data: dict with keys 'alt_tab_count' (int, since last check), 'new_browser_tab_url' (str or None),
#                    'clipboard_content' (str or None)
#   - tutor_state: dict with keys 'current_problem_id', 'current_topic', 'scaffolding_level', 'session_duration',
#                  'last_intervention_time', 'current_concept_difficulty'
# Output:
#   - intervention: dict with keys 'type' (one of ['scaffolding_hint', 'relatability_peer', 'focus_reminder', 'none']),
#                   'message_template', 'payload'

def intercept_external_help_seeking(user_id, activity_data, tutor_state):
    # Step 1: Extract signals from activity_data
    alt_tab_count = activity_data.get('alt_tab_count', 0)
    browser_tab_url = activity_data.get('new_browser_tab_url', None)
    clipboard = activity_data.get('clipboard_content', None)

    # Step 2: Determine if the user is likely seeking external help
    # Signal 1: Multiple rapid alt-tabs (>=2 in a short window)
    rapid_alt_tabs = alt_tab_count >= 2

    # Signal 2: A new browser tab was opened with a search engine or educational domain (e.g., google, wikipedia)
    seeking_external = False
    if browser_tab_url:
        # List of known external help domains
        external_domains = ['google.com', 'bing.com', 'stackoverflow.com', 'wikipedia.org', 'khanacademy.org', 'chegg.com']
        for domain in external_domains:
            if domain in browser_tab_url.lower():
                seeking_external = True
                break

    # Signal 3: User copied problem text (clipboard contains a portion of the current problem or topic)
    copied_problem = False
    if clipboard and tutor_state.get('current_problem_id'):
        # Use a lightweight similarity check: compare clipboard content to known problem text fragments
        current_problem_text = get_current_problem_text(tutor_state['current_problem_id'])  # helper stub
        if current_problem_text and (clipboard in current_problem_text or current_problem_text[:50] in clipboard):
            copied_problem = True

    # Step 3: Combine signals to determine intervention category
    # Priority: copied_problem > seeking_external > rapid_alt_tabs

    if copied_problem:
        # Immediate intervention: offer scaffolding hint OR relatability peer
        # Check the user's current emotional state (from tutor_state or a separate emotional tracker)
        current_emotion = get_current_emotional_state(user_id)  # returns dict with 'frustration', 'confidence', etc.

        if current_emotion.get('frustration', 0) > 0.5:
            # High frustration -> offer a Relatability Target peer
            peer_info = select_peer_for_motivation(user_id, current_emotion, get_peer_database())
            intervention = {
                'type': 'relatability_peer',
                'message_template': f"Wait! {peer_info['message_template']} Let's work through this together instead of searching.",
                'payload': peer_info
            }
        else:
            # Otherwise offer a scaffolding hint tailored to the current problem
            hint = generate_contextual_hint(tutor_state['current_problem_id'], tutor_state['scaffolding_level'])
            intervention = {
                'type': 'scaffolding_hint',
                'message_template': f"I see you're looking for help. Here's a hint that might be exactly what you need: {hint}",
                'payload': {'hint': hint, 'problem_id': tutor_state['current_problem_id']}
            }

        # Log the interception
        log_interception(user_id, 'copied_problem', intervention['type'])
        return intervention

    elif seeking_external:
        # User opened a browser tab to search – give a gentle focus reminder with a promise of faster help
        # Check if we have a relevant hint ready (based on current difficulty)
        if tutor_state.get('current_concept_difficulty', 0.5) > 0.7:
            # Hard problem – offer a peer session or a micro-challenge
            intervention = {
                'type': 'relatability_peer',
                'message_template': "Before you search, let me show you how another student cracked this exact problem.",
                'payload': {'peer_id': 'auto_select'}  # would be resolved by another call
            }
        else:
            intervention = {
                'type': 'focus_reminder',
                'message_template': "You're close! I can help you find the answer right here – no need to search. Try this: [insert quick prompt]",
                'payload': {'quick_prompt': identify_next_step(user_id, tutor_state)}
            }
        log_interception(user_id, 'external_tab', intervention['type'])
        return intervention

    elif rapid_alt_tabs:
        # User alt-tabbing frequently – might be getting distracted or frustrated
        # Offer a short brain break or a modality switch (from the earlier Anticipatory Support)
        intervention = {
            'type': 'focus_reminder',
            'message_template': "It looks like you're bouncing around. Let's refocus – would a quick 30-second puzzle help reset your attention?",
            'payload': {'activity': 'micro_puzzle'}
        }
        log_interception(user_id, 'alt_tabbing', intervention['type'])
        return intervention

    else:
        # No external seeking detected – no intervention
        return {
            'type': 'none',
            'message_template': '',
            'payload': {}
        }


