def trigger_emotional_intervention(user_id: str, 
                                   real_time_metrics: dict, 
                                   historical_data: dict) -> dict:
    """
    Determines the appropriate emotional micro-intervention based on
    real-time behavioral signals and the student's historical response patterns.

    Args:
        user_id: Unique identifier for the student.
        real_time_metrics: Dictionary with keys:
            - 'typing_speed' (float, chars per second)
            - 'voice_pitch' (float, Hz – optional, could be None)
            - 'sentiment_score' (float, -1.0 to 1.0, negative = frustrated)
        historical_data: Dictionary containing:
            - 'intervention_history': list of past intervention outcomes
              (each entry: {'type': str, 'success': bool, 'context': ...})
            - 'learning_state': e.g., 'current_topic_difficulty', 'mastery_level'

    Returns:
        dict with keys:
            - 'intervention_type': one of ['success_story', 'unstuck_prompt', 
                                           'challenge_switch', 'none']
            - 'parameters': dict (e.g., story_id, prompt_text, difficulty_adjustment)
    """

    # --- 1. Extract real-time signals ---
    typing_speed = real_time_metrics.get('typing_speed', None)
    voice_pitch = real_time_metrics.get('voice_pitch', None)
    sentiment = real_time_metrics.get('sentiment_score', 0.0)  # neutral default

    # --- 2. Heuristic thresholds (can be user-tuned per historical data) ---
    FRUSTRATION_SENTIMENT = -0.4          # negative sentiment indicates frustration
    BOREDOM_TYPING_SPEED_UPPER = 1.5      # slow typing may indicate boredom or confusion
    BOREDOM_TYPING_SPEED_LOWER = 0.5      # very slow typing often means stuck
    OVERCONFIDENCE_SENTIMENT = 0.6        # high positive sentiment with fast typing

    # --- 3. Determine base emotional state ---
    # Prioritize sentiment score; typing speed refines.
    if sentiment < FRUSTRATION_SENTIMENT:
        emotional_state = 'frustration'
    elif sentiment > OVERCONFIDENCE_SENTIMENT:
        emotional_state = 'overconfidence'
    else:
        # Use typing speed to differentiate boredom vs. neutral
        if typing_speed is not None:
            if typing_speed < BOREDOM_TYPING_SPEED_LOWER:
                emotional_state = 'stuck'      # (subtype of frustration)
            elif typing_speed < BOREDOM_TYPING_SPEED_UPPER:
                emotional_state = 'boredom'
            else:
                emotional_state = 'neutral'
        else:
            emotional_state = 'neutral'

    # --- 4. Incorporate historical response patterns ---
    # For each possible intervention, look at past success rate for this user.
    intervention_history = historical_data.get('intervention_history', [])
    success_counts = {'success_story': 0, 'unstuck_prompt': 0, 'challenge_switch': 0}
    total_counts = {'success_story': 0, 'unstuck_prompt': 0, 'challenge_switch': 0}

    for entry in intervention_history:
        itype = entry.get('type')
        if itype in success_counts:
            total_counts[itype] += 1
            if entry.get('success', False):
                success_counts[itype] += 1

    def success_rate(itype):
        if total_counts[itype] == 0:
            return 0.5  # default equal probability
        return success_counts[itype] / total_counts[itype]

    # --- 5. Select intervention based on emotional state and best historical match ---
    intervention_type = 'none'
    parameters = {}

    if emotional_state == 'frustration' or emotional_state == 'stuck':
        # Prefer unstuck_prompt if historically successful, else success_story
        if success_rate('unstuck_prompt') >= success_rate('success_story'):
            intervention_type = 'unstuck_prompt'
            # Generate prompt based on current topic (placeholder)
            parameters = {
                'prompt': 'Try breaking the problem into smaller parts. What is the first step?',
                'hint_level': 'medium'
            }
        else:
            intervention_type = 'success_story'
            parameters = {
                'story_id': 'similar_student_win_1',
                'custom_message': 'Another student once struggled here too—here’s how they got it.'
            }

    elif emotional_state == 'boredom':
        # Offer a challenge switch or a more engaging format
        if success_rate('challenge_switch') >= 0.5:
            intervention_type = 'challenge_switch'
            parameters = {
                'new_difficulty': 'increase',
                'alternative_presentation': 'visual'  # e.g., switch from text to diagram
            }
        else:
            # Fallback: success story of someone who found the topic exciting
            intervention_type = 'success_story'
            parameters = {
                'story_id': 'curiosity_spark_3',
                'custom_message': 'Did you know this concept helped invent something amazing?'
            }

    elif emotional_state == 'overconfidence':
        # Gently challenge without diminishing motivation
        intervention_type = 'unstuck_prompt'
        parameters = {
            'prompt': 'Great progress! How about a slightly harder variant?',
            'hint_level': 'advanced'
        }
        # Could also be a challenge_switch to raise difficulty
        # but we choose prompt to maintain their sense of mastery

    # If neutral, no intervention (preserve autonomy)
    # else: already set above

    return {
        'intervention_type': intervention_type,
        'parameters': parameters
    }

